'use strict';
(() => {
  const $ = (id) => document.getElementById(id);
  const poster='../../../frontend/public/brand/auth/creator-studio-poster.jpg';
  const last='../../../frontend/public/brand/auth/creator-studio-last.jpg';
  const state={mode:'text',scenario:'ready',prompt:'',chatOpen:false,materials:0,carrier:'minimax',model:'h3-text'};
  const modeCopy={text:{note:'从一句描述开始',title:'你想做什么镜头？',materialTitle:'加入参考画面（可选）',materialNote:'文生视频无需图片',dropTitle:'有参考画面吗？',dropCopy:'可以稍后添加，不影响先整理镜头。'},frames:{note:'两张图片控制起止画面',title:'这一镜从哪里开始，到哪里结束？',materialTitle:'准备参考画面',materialNote:'首尾帧需要两张图片',dropTitle:'上传首帧与尾帧',dropCopy:'拖入图片，或从资产中选择。图片只用于准备这一镜。'},multi:{note:'用图片说明画面关系',title:'你想让哪些画面保持一致？',materialTitle:'准备参考画面',materialNote:'至少一张参考图片',dropTitle:'上传参考图片',dropCopy:'人物、场景或产品都可以作为参考。'}};
  const modeModels={text:[['h3-text','H3 文字镜头']],frames:[['h3-frames','H3 图片首尾帧']],multi:[['h3-multi-a','H3 多图一致性'],['h3-multi-b','H3 多图细节']]};
  function escape(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function invalidateEstimate(){if(['estimate'].includes(state.scenario)){state.scenario='ready';}updateAvailability();}
  function updateModelOptions(){const select=$('model');const options=modeModels[state.mode]||modeModels.text;select.innerHTML=options.map(([value,label])=>`<option value="${value}">${label}</option>`).join('');state.model=options[0][0];select.value=state.model;}
  function setMode(mode){state.mode=mode;state.materials=0;invalidateEstimate();updateModelOptions();const copy=modeCopy[mode];$('mode-note').textContent=copy.note;$('prompt-title').textContent=copy.title;$('material-title').textContent=copy.materialTitle;$('material-note').textContent=copy.materialNote;$('drop-title').textContent=copy.dropTitle;$('drop-copy').textContent=copy.dropCopy;document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-selected',String(b.dataset.mode===mode));});}
  function updateAvailability(){const banner=$('availability');const status=$('task-status');const start=$('start');status.hidden=true;status.innerHTML='';if(state.scenario==='unavailable'){banner.hidden=false;banner.textContent='生成服务暂未就绪。可以继续整理描述和素材，当前不会估价、扣费或提交任务。';start.disabled=true;start.textContent='暂不可生成';return;}if(state.scenario==='running'){banner.hidden=false;banner.textContent='这一镜已提交，正在执行。修改内容只用于下一次草稿。';start.disabled=true;start.textContent='已提交 · 查看任务';return;}if(state.scenario==='review'){banner.hidden=false;banner.textContent='提交结果需要核对。请不要重复提交这一镜。';start.disabled=true;start.textContent='待核对 · 查看任务';status.hidden=false;status.innerHTML='<strong>提交待核对</strong><span>上游是否受理尚未确认，页面不会自动重试或退款。</span>';return;}if(state.scenario==='failed'){banner.hidden=false;banner.textContent='这一镜执行失败，示例退款已记入余额。';start.disabled=true;start.textContent='已退款 · 按原参数重试';status.hidden=false;status.innerHTML='<strong>失败并退款</strong><span>退款金额和时间应以任务详情与钱包流水为准。</span><button class="secondary" id="retry-draft">按原参数重新开始</button>';return;}if(state.scenario==='delivered'){banner.hidden=true;start.disabled=true;start.textContent='已交付 · 查看作品';status.hidden=false;status.innerHTML='<strong>已交付</strong><span>示例视频已准备好。可预览、下载或保存到作品。</span><div class="status-actions"><button class="secondary" id="download-demo">下载示例</button><button class="primary" id="save-demo">保存到作品</button></div>';return;}banner.hidden=true;start.disabled=false;start.textContent=state.scenario==='estimate'?'确认生成 · 原型演示':'开始创作';}
  function openChat(){state.chatOpen=true;const current=$('prompt').value.trim();$('chat-panel').hidden=false;$('chat-messages').innerHTML=`<div class="chat-message">${escape(current||'女孩在窗边抬头，镜头缓慢推进，保持人物与画风一致。')}</div><div class="chat-message assistant"><strong>S2V · 示例整理</strong><p>我把这句话整理成一个单镜头草稿。你可以继续说动作、镜头距离或画面节奏。</p></div>`;$('chat-panel').scrollIntoView({behavior:'smooth',block:'start'});}
  function showEstimate(){if(state.scenario!=='ready')return;if(!$('prompt').value.trim()){ $('prompt').focus();$('availability').hidden=false;$('availability').textContent='请先写下这一镜的描述，再查看费用。';return;}if(state.mode==='frames'&&state.materials<2){$('availability').hidden=false;$('availability').textContent='首尾帧模式需要准备首帧和尾帧。';return;}if(state.mode==='multi'&&state.materials<1){$('availability').hidden=false;$('availability').textContent='多图模式至少需要一张参考图片。';return;}state.scenario='estimate';updateAvailability();$('availability').hidden=false;$('availability').textContent='本次估价示例：¥0.15（5 秒 × 示例单价）。提交时会重新计算，不锁价。';}
  function showSaved(){try{localStorage.setItem('s2v-canvas-design-draft-v2',JSON.stringify({mode:state.mode,prompt:$('prompt').value,ratio:$('ratio').value,carrier:state.carrier,model:state.model}));$('availability').hidden=false;$('availability').textContent='描述、模式与参数已保存在本机原型。尚未上传的本地图片不会持久化。';}catch{$('availability').hidden=false;$('availability').textContent='浏览器不允许本地保存，请复制描述保留。';}}
  $('scenario').addEventListener('change',e=>{state.scenario=e.target.value;if(state.scenario==='chat'){openChat();return;}if(state.scenario==='estimate'){$('prompt').value=$('prompt').value||'女孩在窗边抬头，镜头缓慢推进，保持人物与画风一致。';}updateAvailability();});
  document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));
  document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{$('prompt').value=b.dataset.example;state.scenario='ready';updateAvailability();$('prompt').focus();}));
  document.querySelectorAll('.inspiration-card').forEach(b=>b.addEventListener('click',()=>{$('prompt').value=b.dataset.example;state.scenario='ready';updateAvailability();$('prompt').focus();window.scrollTo({top:0,behavior:'smooth'});}));
  $('prompt').addEventListener('input',()=>{if(state.scenario==='estimate')invalidateEstimate();});$('ratio').addEventListener('change',invalidateEstimate);$('carrier').addEventListener('change',e=>{state.carrier=e.target.value;invalidateEstimate();});$('model').addEventListener('change',e=>{state.model=e.target.value;invalidateEstimate();});
  $('organize').addEventListener('click',openChat);$('back-to-canvas').addEventListener('click',()=>{$('chat-panel').hidden=true;state.chatOpen=false;window.scrollTo({top:0,behavior:'smooth'});});$('apply-chat').addEventListener('click',()=>{const text=$('chat-input').value.trim();if(text){$('prompt').value+=`\n修改：${text}`;$('chat-input').value='';invalidateEstimate();$('availability').hidden=false;$('availability').textContent='修改已应用到草稿。生成前仍需重新查看费用。';}});
  $('start').addEventListener('click',()=>{if(state.scenario==='estimate'){state.scenario='running';updateAvailability();return;}showEstimate();});$('save-draft').addEventListener('click',showSaved);$('manage-materials').addEventListener('click',()=>$('materials-dialog').showModal());$('sample-materials').addEventListener('click',()=>{state.materials=state.mode==='frames'?2:1;$('materials-dialog').close();invalidateEstimate();$('availability').hidden=true;$('drop-title').textContent=state.mode==='frames'?'已准备首帧与尾帧':'已准备参考图片';});
  document.querySelector('#materials-dialog input[type=file]').addEventListener('change',e=>{const count=e.target.files?.length||0;if(!count)return;state.materials=state.mode==='frames'?Math.min(2,count):1;$('materials-dialog').close();invalidateEstimate();$('availability').hidden=true;$('drop-title').textContent=state.mode==='frames'?(state.materials===2?'已准备首帧与尾帧':'已选择 1 张图片'):'已准备参考图片';});
  $('nav-toggle').addEventListener('click',()=>{const open=document.querySelector('.sidebar').classList.toggle('open');$('nav-toggle').setAttribute('aria-expanded',String(open));});document.addEventListener('click',e=>{const c=e.target.closest('[data-close]');if(c)$(c.dataset.close).close();});
  document.querySelectorAll('[data-nav]').forEach(button=>button.addEventListener('click',()=>{const label=button.dataset.nav;$('availability').hidden=false;$('availability').textContent=`${label}是正式产品入口；本稿只展示创作首页，不会在本地预览中切换真实路由。`;window.scrollTo({top:0,behavior:'smooth'});}));
  document.addEventListener('click',e=>{if(e.target.id==='retry-draft'){state.scenario='ready';updateAvailability();}if(e.target.id==='download-demo'||e.target.id==='save-demo'){$('availability').hidden=false;$('availability').textContent='这是设计稿中的示例动作，未读取真实任务、文件或作品数据。';}});
  try{const saved=JSON.parse(localStorage.getItem('s2v-canvas-design-draft-v2')||'null');if(saved?.prompt){$('prompt').value=saved.prompt;if(saved.ratio)$('ratio').value=saved.ratio;if(saved.mode)setMode(saved.mode);if(saved.model&&[...$('model').options].some(option=>option.value===saved.model)){$('model').value=saved.model;state.model=saved.model;}if(saved.carrier){$('carrier').value=saved.carrier;state.carrier=saved.carrier;}}}catch{}
  setMode('text');updateAvailability();
})();
